values
  ('3d1830b3-293c-4cbe-be22-08212023f900', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Foundations of Elementary Mathematics Teaching and Mathematical Identity', 'Elementary mathematics teaching begins with a view of children as sense-makers. This topic frames math as reasoning, communication, representation, and productive struggle rather than memorized procedures alone.', 0),
  ('15bf01eb-9b35-429a-ab1b-0d88dc17663b', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '3d1830b3-293c-4cbe-be22-08212023f900', 'subtopic'::public.curated_course_node_type, 'What elementary math teaching is for', 'Why it matters: Teachers learn to design experiences that build flexible thinking, confidence, and durable mathematical understanding.', 0),
