  ('eed639b9-c0f4-4161-9ca1-dd1048af559a', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '9876e976-4a6a-4975-a4c6-ffebdb4bb034', 'concept'::public.curated_course_node_type, 'teacher expectations', null, 3),
  ('5ed38188-e68a-459b-8c07-851eab6d01b0', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '3d1830b3-293c-4cbe-be22-08212023f900', 'subtopic'::public.curated_course_node_type, 'Effective teaching practices', 'Why it matters: Research-based practices give teachers a shared language for planning, launching, facilitating, and reflecting on math lessons.', 2),
