  ('bb28de67-8038-4636-af71-0315af186d11', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '5ed38188-e68a-459b-8c07-851eab6d01b0', 'concept'::public.curated_course_node_type, 'reflection routines', null, 3),
  ('bc3527e5-3ef9-4207-82c8-03d4482704ec', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Learning Progressions, Standards, and Curriculum Coherence', 'This section connects grade-level teaching to the larger developmental arc of K-6 mathematics. Teachers learn to see how today''s lesson depends on prior ideas and prepares students for future ones.', 1),
  ('5de33baf-7c7f-491c-b3f1-9780dabc5817', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'bc3527e5-3ef9-4207-82c8-03d4482704ec', 'subtopic'::public.curated_course_node_type, 'Standards and progressions', 'Why it matters: Standards become useful when teachers understand the learning trajectory behind them, not just the grade-level checklist.', 0),
  ('95bf79c5-78d7-443e-9a43-e6e3d9f04fb9', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '5de33baf-7c7f-491c-b3f1-9780dabc5817', 'concept'::public.curated_course_node_type, 'Common Core domains', null, 0),
