  ('69814ae1-1839-48f0-97f2-3ec535652990', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '5de33baf-7c7f-491c-b3f1-9780dabc5817', 'concept'::public.curated_course_node_type, 'prerequisite knowledge', null, 3),
