  ('e85b575a-b779-4f68-8173-2126d40d8970', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '6fcac5b9-18a4-4b68-8b7f-8c37b5f74ea0', 'concept'::public.curated_course_node_type, 'scope and sequence', null, 0),
