  ('ad7b63db-eb37-49d2-8d23-cc8716d61f21', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '6fcac5b9-18a4-4b68-8b7f-8c37b5f74ea0', 'concept'::public.curated_course_node_type, 'adaptation decisions', null, 3),
  ('b4803087-1114-4d71-b345-21e9c126b0e8', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'bc3527e5-3ef9-4207-82c8-03d4482704ec', 'subtopic'::public.curated_course_node_type, 'Backward design', 'Why it matters: Planning starts from evidence of understanding, then selects tasks, questions, and supports that make that understanding visible.', 2),
  ('f5bc7754-7af6-480f-aa47-5e8b7867f7ec', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'b4803087-1114-4d71-b345-21e9c126b0e8', 'concept'::public.curated_course_node_type, 'learning goals', null, 0),
