  ('213d7e99-ccec-4796-86a4-cb2b23c98d19', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'b4803087-1114-4d71-b345-21e9c126b0e8', 'concept'::public.curated_course_node_type, 'assessment evidence', null, 2),
  ('7433d321-b0ba-4ef5-8754-ecf51309784c', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'b4803087-1114-4d71-b345-21e9c126b0e8', 'concept'::public.curated_course_node_type, 'lesson arcs', null, 3),
  ('0bba44b2-7bed-4cc1-acab-37b8f8ec49d4', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Number Sense, Counting, Place Value, and Base-Ten Reasoning', 'Number sense is the foundation for nearly every elementary math idea. This topic develops children''s ability to count, compare, compose, decompose, estimate, and reason with our base-ten system.', 2),
  ('ea2e32ad-f701-4889-b1f0-d87238592a63', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '0bba44b2-7bed-4cc1-acab-37b8f8ec49d4', 'subtopic'::public.curated_course_node_type, 'Counting and cardinality', 'Why it matters: Counting is a conceptual system that links number words, objects, order, quantity, and comparison.', 0),
  ('a9a1cb07-844a-4140-95ef-aa6825cede96', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'ea2e32ad-f701-4889-b1f0-d87238592a63', 'concept'::public.curated_course_node_type, 'one-to-one correspondence', null, 0),
