  ('e59f0ece-3a6f-4fcf-902c-0b0ae114cfae', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'ea2e32ad-f701-4889-b1f0-d87238592a63', 'concept'::public.curated_course_node_type, 'subitizing', null, 3),
  ('6cb23fcb-acf0-4535-b419-1d2e05515a49', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '0bba44b2-7bed-4cc1-acab-37b8f8ec49d4', 'subtopic'::public.curated_course_node_type, 'Place value', 'Why it matters: Place value helps students treat numbers as structured quantities, making later computation and estimation meaningful.', 1),
