  ('26c8ff90-2cde-408b-ac1c-fecb6a084919', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '328f6b60-fdde-4a0f-b7b9-23925c7e9225', 'concept'::public.curated_course_node_type, 'number lines', null, 3),
  ('e0060e30-3c81-4b48-978d-f545d7e743f1', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Addition, Subtraction, Multiplication, and Division Concepts', 'Operations become powerful when children understand the situations, relationships, and representations behind them. This topic moves from problem structures to strategies and fluency.', 3),
  ('52860d6f-c6e9-4164-af92-cdbbce34e1a5', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'e0060e30-3c81-4b48-978d-f545d7e743f1', 'subtopic'::public.curated_course_node_type, 'Additive reasoning', 'Why it matters: Addition and subtraction are related operations used to join, separate, compare, and find unknowns.', 0),
