  ('764c594a-fced-4422-8f62-3631772f7056', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'e0060e30-3c81-4b48-978d-f545d7e743f1', 'subtopic'::public.curated_course_node_type, 'Multiplicative reasoning', 'Why it matters: Multiplication and division extend counting into equal groups, arrays, rates, and comparisons.', 1),
