  ('84a3fd4d-2a8b-460e-98af-10ff93c45ca8', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '764c594a-fced-4422-8f62-3631772f7056', 'concept'::public.curated_course_node_type, 'partitive division', null, 4),
  ('ec9e0b49-8217-48e3-9ec7-08488abb4ca8', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'e0060e30-3c81-4b48-978d-f545d7e743f1', 'subtopic'::public.curated_course_node_type, 'Fluency development', 'Why it matters: Fluency means accuracy, efficiency, flexibility, and understanding, not timed recall alone.', 2),
