  ('b055b323-615f-4768-962d-71823610a65c', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'ec9e0b49-8217-48e3-9ec7-08488abb4ca8', 'concept'::public.curated_course_node_type, 'games', null, 2),
  ('962735f9-0466-4f8d-9796-e3b866217229', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'ec9e0b49-8217-48e3-9ec7-08488abb4ca8', 'concept'::public.curated_course_node_type, 'practice design', null, 3),
  ('328ea6d4-18ce-4a12-9914-2c03ec555b4f', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Fractions, Decimals, Ratios, and Percent', 'Rational number concepts are a major transition in elementary mathematics. Teachers learn to help students coordinate units, equivalence, magnitude, and operations across multiple representations.', 4),
  ('c46e2988-ace8-4eee-92c5-5506d992bc87', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '328ea6d4-18ce-4a12-9914-2c03ec555b4f', 'subtopic'::public.curated_course_node_type, 'Fractions as numbers', 'Why it matters: Students need to see fractions as quantities on a number line, not only shaded parts of shapes.', 0),
  ('cb9a9c09-cff6-4592-9e53-7b90e4b3791e', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'c46e2988-ace8-4eee-92c5-5506d992bc87', 'concept'::public.curated_course_node_type, 'unit fractions', null, 0),
  ('dcb3db99-8222-4acc-a648-3efaf16ed3e5', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'c46e2988-ace8-4eee-92c5-5506d992bc87', 'concept'::public.curated_course_node_type, 'iteration', null, 1),
  ('51270e41-ca9a-47d4-ac3a-5184f5a81d16', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'c46e2988-ace8-4eee-92c5-5506d992bc87', 'concept'::public.curated_course_node_type, 'partitioning', null, 2),
