  ('18a4aecb-7d3c-4e26-89ea-b7999a9fa476', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '25ef6189-3b56-4227-9a6c-7029fe64e0ab', 'concept'::public.curated_course_node_type, 'decimal place value', null, 0),
