  ('d6d9f398-ae81-4ee4-80d2-a1239647a502', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'fcd67133-c1bb-4906-b2a9-fe5e95b46f23', 'subtopic'::public.curated_course_node_type, 'Geometry and spatial visualization', 'Why it matters: Children build geometric reasoning by composing shapes, describing attributes, and visualizing transformations.', 0),
