  ('931e6d22-f4ec-4ef2-8ace-6b9160df1f5b', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Algebraic Thinking, Patterns, Functions, and Early Generalization', 'Algebra in elementary grades is about noticing structure, expressing generality, and reasoning about relationships. It gives students language for patterns long before formal symbolic algebra.', 6),
  ('39265d3c-63c9-4f87-bcbe-3b620108425c', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '931e6d22-f4ec-4ef2-8ace-6b9160df1f5b', 'subtopic'::public.curated_course_node_type, 'Patterns and structure', 'Why it matters: Students learn to identify, extend, describe, and justify patterns using words, tables, drawings, and symbols.', 0),
