  ('9e11a510-7de9-48ae-84fa-073c650a16fe', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '39265d3c-63c9-4f87-bcbe-3b620108425c', 'concept'::public.curated_course_node_type, 'skip counting', null, 2),
