  ('57b64bf4-2252-46b2-a4ca-816cc92265e3', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '931e6d22-f4ec-4ef2-8ace-6b9160df1f5b', 'subtopic'::public.curated_course_node_type, 'Equality and unknowns', 'Why it matters: A relational view of the equal sign helps children solve equations meaningfully.', 1),
