  ('8f09c763-2b8c-4c89-a21f-f52c331d4191', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'dc7cad3b-34ad-4b71-94cb-64f95f1b96de', 'concept'::public.curated_course_node_type, 'input-output tables', null, 0),
