  ('0323c74d-f42b-47ae-a808-06d074b92ed0', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Problem Solving, Mathematical Modeling, and Reasoning', 'Problem solving teaches students to make sense of situations, choose strategies, test ideas, and explain why results make sense. Modeling connects classroom math to real contexts and decisions.', 7),
