  ('5573ac60-2116-4490-8f6e-e6f4e7b05192', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', 'c5705e56-d036-4114-9830-f5b10f95f168', 'concept'::public.curated_course_node_type, 'draw a diagram', null, 0),
