  ('1ce2d15e-a773-47ab-b6b0-d50d1b550367', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Equity, Culturally Responsive Math Teaching, and Math Anxiety', 'Elementary math teaching treats equity as part of mathematical quality. This topic focuses on access, representation, identity, and classroom conditions that reduce anxiety and expand participation.', 11),
  ('b5fc3e07-9cfc-4f9b-a79b-b4e0ab16e691', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', '1ce2d15e-a773-47ab-b6b0-d50d1b550367', 'subtopic'::public.curated_course_node_type, 'Equitable participation', 'Why it matters: Teachers design routines that distribute authority, visibility, and intellectual responsibility across students.', 0),
