  ('0a952519-9425-484d-be78-d1f0f33badf5', 'c5d6e7f8-9a0b-4c82-9d12-2f3a4b5c6d22', null, 'topic'::public.curated_course_node_type, 'Differentiation, UDL, MTSS, and Inclusive Math Instruction', 'Inclusive math instruction anticipates learner variability and provides multiple pathways into rigorous ideas. Teachers learn to support students with disabilities, multilingual learners, and advanced learners without lowering expectations.', 12),
